import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SlashingXProps = Record<string, any>;

const SlashingX: React.FC<SlashingXProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 4,
  xColor = "#ff2a2a",
  strokeWidth = 60,
  staggerFrames = 8,
  scaleImpact = 1.08,
  glowIntensity = 40,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive calculations: ensure the 'X' spans across the entire viewport
  const svgSize = Math.max(width, height) * 1.5;
  const lineLength = svgSize * Math.SQRT2;

  // First Slash Animation
  const progress1 = spring({
    frame,
    fps,
    config: { stiffness: 180, damping: 14, mass: 0.8 },
  });

  // Second Slash Animation (Delayed)
  const progress2 = spring({
    frame: frame - staggerFrames,
    fps,
    config: { stiffness: 180, damping: 14, mass: 0.8 },
  });

  // Impact scale effect exactly when the second slash lands
  const impactSpring = spring({
    frame: frame - staggerFrames - 4,
    fps,
    config: { stiffness: 300, damping: 10 },
  });

  const currentScale = interpolate(impactSpring, [0, 1], [1, scaleImpact]);
  const currentRotation = interpolate(progress1, [0, 1], [0, -4]);

  // Stroke offsets
  const offset1 = interpolate(progress1, [0, 1], [lineLength, 0]);
  const offset2 = interpolate(progress2, [0, 1], [lineLength, 0]);

  // Alpha fade out near the end of the duration
  const totalFrames = durationInSeconds * fps;
  const fadeOutStart = totalFrames - 15;
  const opacity = interpolate(
    frame,
    [fadeOutStart, totalFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden", opacity }}>
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${currentScale}) rotate(${currentRotation}deg)`,
          transition: "none",
        }}
      >
        <svg
          width={svgSize}
          height={svgSize}
          viewBox={`0 0 ${svgSize} ${svgSize}`}
          style={{
            overflow: "visible",
            filter: `drop-shadow(0px 0px ${glowIntensity}px ${xColor}) drop-shadow(0px 0px ${glowIntensity * 0.5}px ${xColor})`,
            transition: "none",
          }}
        >
          {/* First Slash: Top-Left to Bottom-Right */}
          <line
            x1={0}
            y1={0}
            x2={svgSize}
            y2={svgSize}
            stroke={xColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={lineLength}
            strokeDashoffset={offset1}
            style={{ transition: "none" }}
          />

          {/* Second Slash: Top-Right to Bottom-Left */}
          <line
            x1={svgSize}
            y1={0}
            x2={0}
            y2={svgSize}
            stroke={xColor}
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={lineLength}
            strokeDashoffset={offset2}
            style={{ transition: "none" }}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default SlashingX;